  Object.assign(translations.en, {'Mis pedidos — NNytro':'My orders — NNytro','Tickets de soporte — NNytro':'Support tickets — NNytro','Comisiones finalizadas — NNytro':'Completed commissions — NNytro','Comisiones finalizadas':'Completed commissions','Comisiones realizadas':'Completed commissions','MIS PEDIDOS':'MY ORDERS','SOPORTE':'SUPPORT','Consultá el estado de tus pedidos, cotizaciones, pagos y tickets.':'Check the status of your orders, quotes, payments, and tickets.','Cada pedido tiene un ticket privado. Abrilo para escribirnos y seguir la conversación.':'Each order has a private support ticket. Open it to message me and continue the conversation.','Abrí un ticket':'Open a ticket','Acá aparecen los encargos que ya terminaste y pagaste. Cuando publique uno, vas a poder dejar tu reseña.':'Here you’ll find commissions you’ve finished and paid for. Once I publish one, you can leave a review.','Todavía no tenés comisiones finalizadas.':'You don’t have any completed commissions yet.','Tu comisión ya está publicada':'Your commission has been published','Ya podés ver la publicación y dejar una reseña con estrellas.':'You can view the post and leave a star rating now.','El estado del pedido cambió. Entrá a Mis pedidos para ver los detalles.':'Your order status changed. Open My orders for details.'});
  Object.assign(translations.pt, {'Mis pedidos — NNytro':'Meus pedidos — NNytro','Tickets de soporte — NNytro':'Tickets de suporte — NNytro','Comisiones finalizadas — NNytro':'Comissões finalizadas — NNytro','Comisiones finalizadas':'Comissões finalizadas','Comisiones realizadas':'Trabalhos concluídos','MIS PEDIDOS':'MEUS PEDIDOS','SOPORTE':'SUPORTE','Consultá el estado de tus pedidos, cotizaciones, pagos y tickets.':'Consulte o status dos seus pedidos, orçamentos, pagamentos e tickets.','Cada pedido tiene un ticket privado. Abrilo para escribirnos y seguir la conversación.':'Cada pedido tem um ticket privado. Abra-o para me escrever e continuar a conversa.','Abrí un ticket':'Abrir um ticket','Acá aparecen los encargos que ya terminaste y pagaste. Cuando publique uno, vas a poder dejar tu reseña.':'Aqui aparecem os trabalhos que você concluiu e pagou. Quando eu publicar um, você poderá deixar sua avaliação.','Todavía no tenés comisiones finalizadas.':'Você ainda não tem trabalhos concluídos.','Tu comisión ya está publicada':'Seu trabalho foi publicado','Ya podés ver la publicación y dejar una reseña con estrellas.':'Você já pode ver a publicação e deixar uma avaliação com estrelas.','El estado del pedido cambió. Entrá a Mis pedidos para ver los detalles.':'O status do pedido mudou. Acesse Meus pedidos para ver os detalhes.'});
  Object.assign(translations.en, {'Creá un ticket para hablar directamente con NNytro. Cada ticket tiene su propia conversación privada.':'Create a ticket to talk directly with NNytro. Every ticket has its own private conversation.','SOPORTE NNytro':'NNytro SUPPORT','Abrí un ticket nuevo':'Open a new ticket','Los tickets son chats separados de tus pedidos. NNytro te responde desde esta cuenta.':'Tickets are separate from your orders. NNytro will reply from this account.','Asunto':'Subject','¿Sobre qué necesitás ayuda?':'What do you need help with?','Contame cómo puedo ayudarte':'Tell me how I can help','Crear ticket y enviar':'Create ticket and send','Tus tickets':'Your tickets','Todavía no creaste tickets. Usá el formulario para hablar con NNytro.':'You haven’t created any tickets yet. Use the form to talk to NNytro.','Ticket de soporte':'Support ticket','Todavía no hay mensajes en este ticket.':'There are no messages in this ticket yet.','Tu mensaje':'Your message','Respondé desde la cuenta de NNytro':'Reply from the NNytro account','Escribile a NNytro':'Message NNytro','Enviar mensaje':'Send message','Creando ticket…':'Creating ticket…','Ticket creado. NNytro recibió tu mensaje.':'Ticket created. NNytro received your message.','Estás respondiendo como NNytro.':'You are replying as NNytro.','Tus tickets se guardan en esta cuenta.':'Your tickets are saved to this account.','Iniciá sesión para crear un ticket y hablar directamente con NNytro.':'Sign in to create a ticket and talk directly with NNytro.','Tickets de clientes':'Customer tickets','Bandeja de tickets':'Ticket inbox','Todavía no hay tickets de clientes.':'There are no customer tickets yet.','Abierto':'Open','Cerrado':'Closed','Panel de NNytro':'NNytro support inbox','Cuenta conectada':'Account connected','Esta es la bandeja de NNytro. Para abrir un ticket, cerrá la sesión administradora e ingresá con tu cuenta de cliente.':'This is NNytro’s support inbox. To open a ticket, sign out of the admin account and sign in with your customer account.'});
