  Object.assign(translations.en, {'¿Tenés una duda o necesitás ayuda? Creá un ticket directamente; no hace falta elegir un pedido. Cada ticket tiene su propia conversación privada.':'Have a question or need help? Create a ticket directly; you don’t need to choose an order. Each ticket has its own private conversation.','Esta cuenta administra y responde los tickets. Para enviar una consulta, iniciá sesión con tu cuenta de cliente.':'This account manages and replies to tickets. To send a question, sign in with your customer account.'});
